/**
 * Weekly item_whitelist builder — eBay sold + Vinted/Depop listed comps per brand.
 *
 * Secrets: EBAY_APP_ID, SCRAPINGBEE_API_KEY, SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY
 * Optional: BUILD_WHITELIST_SECRET (cron/manual invoke without JWT)
 *
 * Deploy: `supabase functions deploy build-whitelist`
 *
 * Scheduling (pick one):
 * 1. Supabase Dashboard → Edge Functions → build-whitelist → Cron → `0 3 * * 0` (Sun 03:00 UTC)
 *    Body: `{"brand_offset":0,"brand_limit":4,"chain":true}`
 * 2. pg_cron: see `supabase/migrations/20260601120100_build_whitelist_cron.sql`
 *
 * Timeout strategy:
 * - Default `brand_limit` = 4 brands per invocation (~12 ScrapingBee + 4 eBay calls).
 * - Pass `"chain": true` to fire-and-forget the next batch until all 30 brands are done.
 * - Full weekly run ≈ 8 chained invocations; avoid `brand_limit: 30` in one call (150s+ risk).
 *
 * POST body (all optional):
 * `{ "brand_offset": 0, "brand_limit": 4, "chain": true, "platforms": ["ebay","vinted","depop"] }`
 */
import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
import { fetchEbaySoldListingsForWhitelist } from "./_shared/ebayWhitelistFetch.ts";
import { logEdgeSecretsAtStartup } from "./_shared/edgeSecrets.ts";
import {
  fetchDepopListingsForWhitelist,
  fetchVintedListingsForWhitelist,
} from "./_shared/htmlWhitelistScrape.ts";
import { itemTypeFromTitle } from "./_shared/itemTypeFromTitle.ts";
import { withRequestLog, type RequestLogHandle } from "./_shared/requestLog.ts";
import {
  depopSearchUrl,
  vintedSearchUrl,
  WHITELIST_BRANDS,
} from "./_shared/whitelistBrands.ts";

const JSON_HEADERS = { "Content-Type": "application/json" };
const DEFAULT_BRAND_LIMIT = 4;
const PLATFORMS = ["ebay", "vinted", "depop"] as const;
type Platform = (typeof PLATFORMS)[number];

type WhitelistInsertRow = {
  brand: string;
  platform: Platform;
  listing_id: string;
  listing_title: string;
  price: number;
  condition: string | null;
  category: string | null;
  image_url: string | null;
  listing_url: string | null;
  date_scraped: string;
  date_sold: string | null;
  item_type: string;
};

type BuildBody = {
  brand_offset?: number;
  brand_limit?: number;
  chain?: boolean;
  platforms?: Platform[];
};

function parseBody(raw: unknown): BuildBody {
  if (!raw || typeof raw !== "object") return {};
  const o = raw as Record<string, unknown>;
  const brand_offset = typeof o.brand_offset === "number" && o.brand_offset >= 0
    ? Math.floor(o.brand_offset)
    : undefined;
  const brand_limit = typeof o.brand_limit === "number" && o.brand_limit > 0
    ? Math.min(30, Math.floor(o.brand_limit))
    : undefined;
  const chain = o.chain === true;
  let platforms: Platform[] | undefined;
  if (Array.isArray(o.platforms)) {
    platforms = o.platforms.filter((p): p is Platform =>
      p === "ebay" || p === "vinted" || p === "depop"
    );
  }
  return { brand_offset, brand_limit, chain, platforms };
}

function parseDateSold(raw: string | null): string | null {
  if (!raw) return null;
  const ms = Date.parse(raw);
  if (!Number.isFinite(ms)) return null;
  return new Date(ms).toISOString();
}

function authorize(req: Request): boolean {
  const cronSecret = (Deno.env.get("BUILD_WHITELIST_SECRET") ?? "").trim();
  if (cronSecret) {
    const hdr = (req.headers.get("X-Build-Whitelist-Secret") ??
      req.headers.get("x-build-whitelist-secret") ?? "").trim();
    if (hdr === cronSecret) return true;
  }
  const auth = (req.headers.get("Authorization") ?? "").trim();
  const serviceKey = (Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? "").trim();
  if (serviceKey && auth === `Bearer ${serviceKey}`) return true;
  return false;
}

async function existingListingIds(
  supabase: ReturnType<typeof createClient>,
  platform: Platform,
  ids: string[],
): Promise<Set<string>> {
  if (ids.length === 0) return new Set();
  const { data, error } = await supabase
    .from("item_whitelist")
    .select("listing_id")
    .eq("platform", platform)
    .in("listing_id", ids);
  if (error) {
    console.error("[build-whitelist] dedup lookup failed", platform, error.message);
    return new Set();
  }
  return new Set((data ?? []).map((r: { listing_id: string }) => r.listing_id));
}

async function insertRows(
  supabase: ReturnType<typeof createClient>,
  rows: WhitelistInsertRow[],
): Promise<number> {
  if (rows.length === 0) return 0;
  const { error } = await supabase.from("item_whitelist").insert(rows);
  if (error) {
    console.error("[build-whitelist] insert error", error.code, error.message);
    return 0;
  }
  return rows.length;
}

async function processBrand(
  supabase: ReturnType<typeof createClient>,
  brand: string,
  platforms: Platform[],
): Promise<{ inserted: number; skipped: number; errors: string[] }> {
  const nowIso = new Date().toISOString();
  let inserted = 0;
  let skipped = 0;
  const errors: string[] = [];

  console.log("[build-whitelist] brand start", brand);

  if (platforms.includes("ebay")) {
    try {
      const listings = await fetchEbaySoldListingsForWhitelist(brand);
      const ids = listings.map((l) => l.listing_id);
      const existing = await existingListingIds(supabase, "ebay", ids);
      const rows: WhitelistInsertRow[] = [];
      for (const l of listings) {
        if (existing.has(l.listing_id)) {
          skipped++;
          continue;
        }
        rows.push({
          brand,
          platform: "ebay",
          listing_id: l.listing_id,
          listing_title: l.listing_title,
          price: l.price,
          condition: l.condition,
          category: l.category,
          image_url: l.image_url,
          listing_url: l.listing_url,
          date_scraped: nowIso,
          date_sold: parseDateSold(l.date_sold),
          item_type: itemTypeFromTitle(l.listing_title),
        });
      }
      inserted += await insertRows(supabase, rows);
      console.log("[build-whitelist] ebay", brand, { fetched: listings.length, inserted: rows.length });
    } catch (e) {
      const msg = e instanceof Error ? e.message : String(e);
      errors.push(`ebay:${msg}`);
      console.error("[build-whitelist] ebay failed", brand, msg);
    }
  }

  if (platforms.includes("vinted")) {
    try {
      const listings = await fetchVintedListingsForWhitelist(vintedSearchUrl(brand));
      const ids = listings.map((l) => l.listing_id);
      const existing = await existingListingIds(supabase, "vinted", ids);
      const rows: WhitelistInsertRow[] = [];
      for (const l of listings) {
        if (existing.has(l.listing_id)) {
          skipped++;
          continue;
        }
        rows.push({
          brand,
          platform: "vinted",
          listing_id: l.listing_id,
          listing_title: l.listing_title,
          price: l.price,
          condition: l.condition,
          category: null,
          image_url: l.image_url,
          listing_url: l.listing_url,
          date_scraped: nowIso,
          date_sold: null,
          item_type: itemTypeFromTitle(l.listing_title),
        });
      }
      inserted += await insertRows(supabase, rows);
      console.log("[build-whitelist] vinted", brand, { fetched: listings.length, inserted: rows.length });
    } catch (e) {
      const msg = e instanceof Error ? e.message : String(e);
      errors.push(`vinted:${msg}`);
      console.error("[build-whitelist] vinted failed", brand, msg);
    }
  }

  if (platforms.includes("depop")) {
    try {
      const listings = await fetchDepopListingsForWhitelist(depopSearchUrl(brand));
      const ids = listings.map((l) => l.listing_id);
      const existing = await existingListingIds(supabase, "depop", ids);
      const rows: WhitelistInsertRow[] = [];
      for (const l of listings) {
        if (existing.has(l.listing_id)) {
          skipped++;
          continue;
        }
        rows.push({
          brand,
          platform: "depop",
          listing_id: l.listing_id,
          listing_title: l.listing_title,
          price: l.price,
          condition: l.condition,
          category: null,
          image_url: l.image_url,
          listing_url: l.listing_url,
          date_scraped: nowIso,
          date_sold: null,
          item_type: itemTypeFromTitle(l.listing_title),
        });
      }
      inserted += await insertRows(supabase, rows);
      console.log("[build-whitelist] depop", brand, { fetched: listings.length, inserted: rows.length });
    } catch (e) {
      const msg = e instanceof Error ? e.message : String(e);
      errors.push(`depop:${msg}`);
      console.error("[build-whitelist] depop failed", brand, msg);
    }
  }

  console.log("[build-whitelist] brand done", brand, { inserted, skipped, errors: errors.length });
  return { inserted, skipped, errors };
}

function chainNextInvocation(body: BuildBody, nextOffset: number): void {
  const supabaseUrl = (Deno.env.get("SUPABASE_URL") ?? "").trim();
  const serviceKey = (Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? "").trim();
  if (!supabaseUrl || !serviceKey) {
    console.warn("[build-whitelist] chain skipped — missing SUPABASE_URL or service role");
    return;
  }

  const payload = {
    brand_offset: nextOffset,
    brand_limit: body.brand_limit ?? DEFAULT_BRAND_LIMIT,
    chain: true,
    platforms: body.platforms,
  };

  const headers: Record<string, string> = {
    "Content-Type": "application/json",
    Authorization: `Bearer ${serviceKey}`,
  };
  const cronSecret = (Deno.env.get("BUILD_WHITELIST_SECRET") ?? "").trim();
  if (cronSecret) headers["X-Build-Whitelist-Secret"] = cronSecret;

  const chainPromise = fetch(`${supabaseUrl}/functions/v1/build-whitelist`, {
    method: "POST",
    headers,
    body: JSON.stringify(payload),
  }).then((res) => {
    console.log("[build-whitelist] chained invocation", res.status, "offset", nextOffset);
  }).catch((e) => {
    console.error("[build-whitelist] chain failed", e instanceof Error ? e.message : String(e));
  });

  const er = (globalThis as { EdgeRuntime?: { waitUntil?: (p: Promise<unknown>) => void } }).EdgeRuntime;
  if (er?.waitUntil) {
    er.waitUntil(chainPromise);
  }
}

serve(
  withRequestLog("build-whitelist", async (req, log: RequestLogHandle) => {
    logEdgeSecretsAtStartup("build-whitelist");

    if (req.method === "OPTIONS") {
      return new Response(null, { status: 204 });
    }

    if (req.method !== "POST") {
      return new Response(JSON.stringify({ error: "Method not allowed" }), {
        status: 405,
        headers: JSON_HEADERS,
      });
    }

    if (!authorize(req)) {
      return new Response(JSON.stringify({ error: "Unauthorized" }), {
        status: 401,
        headers: JSON_HEADERS,
      });
    }

    const supabaseUrl = (Deno.env.get("SUPABASE_URL") ?? "").trim();
    const serviceKey = (Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? "").trim();
    if (!supabaseUrl || !serviceKey) {
      log.setDetail("missing supabase env");
      return new Response(JSON.stringify({ error: "Server not configured" }), {
        status: 503,
        headers: JSON_HEADERS,
      });
    }

    let body: BuildBody = {};
    try {
      const text = await req.text();
      if (text.trim()) body = parseBody(JSON.parse(text));
    } catch {
      return new Response(JSON.stringify({ error: "Invalid JSON body" }), {
        status: 400,
        headers: JSON_HEADERS,
      });
    }

    const brandOffset = body.brand_offset ?? 0;
    const brandLimit = body.brand_limit ?? DEFAULT_BRAND_LIMIT;
    const platforms = body.platforms?.length ? body.platforms : [...PLATFORMS];
    const brandsSlice = WHITELIST_BRANDS.slice(brandOffset, brandOffset + brandLimit);

    if (brandsSlice.length === 0) {
      log.setDetail("no brands in range");
      return new Response(
        JSON.stringify({
          ok: true,
          message: "No brands in range",
          brand_offset: brandOffset,
          total_brands: WHITELIST_BRANDS.length,
        }),
        { status: 200, headers: JSON_HEADERS },
      );
    }

    log.setDetail(`brands ${brandOffset}+${brandsSlice.length}`);

    const supabase = createClient(supabaseUrl, serviceKey);
    const perBrand: Record<string, { inserted: number; skipped: number; errors: string[] }> = {};
    let totalInserted = 0;
    let totalSkipped = 0;

    for (const brand of brandsSlice) {
      const result = await processBrand(supabase, brand, platforms);
      perBrand[brand] = result;
      totalInserted += result.inserted;
      totalSkipped += result.skipped;
    }

    const nextOffset = brandOffset + brandsSlice.length;
    const hasMore = nextOffset < WHITELIST_BRANDS.length;
    if (body.chain && hasMore) {
      chainNextInvocation(body, nextOffset);
    }

    const summary = {
      ok: true,
      brand_offset: brandOffset,
      brand_limit: brandLimit,
      brands_processed: brandsSlice,
      total_brands: WHITELIST_BRANDS.length,
      next_brand_offset: hasMore ? nextOffset : null,
      chained: Boolean(body.chain && hasMore),
      total_inserted: totalInserted,
      total_skipped_duplicates: totalSkipped,
      per_brand: perBrand,
      platforms,
    };

    console.log("[build-whitelist] run complete", JSON.stringify({
      total_inserted: totalInserted,
      brands: brandsSlice.length,
      chained: summary.chained,
    }));

    return new Response(JSON.stringify(summary), {
      status: 200,
      headers: JSON_HEADERS,
    });
  }),
);

/**
 * eBay Finding API — raw sold listings for item_whitelist (up to 100 per brand).
 */
import { ebayAppId } from "./edgeSecrets.ts";

const FINDING_BASE = "https://svcs.ebay.com/services/search/FindingService/v1";
const FINDING_VERSION = "1.13.0";
const FINDING_TIMEOUT_MS = 25_000;
const ENTRIES_PER_PAGE = 100;

export type EbayWhitelistListing = {
  listing_id: string;
  listing_title: string;
  price: number;
  condition: string | null;
  category: string | null;
  listing_url: string | null;
  image_url: string | null;
  date_sold: string | null;
};

function first<T>(v: T | T[] | undefined | null): T | undefined {
  if (v === undefined || v === null) return undefined;
  return Array.isArray(v) ? v[0] : v;
}

function buildFindingUrl(keywords: string, appId: string): string {
  const params = new URLSearchParams({
    "OPERATION-NAME": "findCompletedItems",
    "SERVICE-VERSION": FINDING_VERSION,
    "SECURITY-APPNAME": appId,
    "RESPONSE-DATA-FORMAT": "JSON",
    "REST-PAYLOAD": "",
    keywords: keywords.trim(),
    "paginationInput.entriesPerPage": String(ENTRIES_PER_PAGE),
    "paginationInput.pageNumber": "1",
    "GLOBAL-ID": "EBAY-GB",
  });
  params.append("itemFilter(0).name", "SoldItemsOnly");
  params.append("itemFilter(0).value", "true");
  params.append("itemFilter(1).name", "LocatedIn");
  params.append("itemFilter(1).value", "GB");
  return `${FINDING_BASE}?${params.toString()}`;
}

function parsePrice(item: Record<string, unknown>): number | null {
  const sellingStatus = first(item.sellingStatus as Record<string, unknown>[] | Record<string, unknown>);
  const currentPrice = sellingStatus
    ? first(sellingStatus.currentPrice as Record<string, unknown>[] | Record<string, unknown>)
    : undefined;
  if (!currentPrice) return null;
  const raw = currentPrice["@__value__"] ?? currentPrice.__value__ ?? currentPrice.value;
  const n = typeof raw === "string" ? parseFloat(raw) : typeof raw === "number" ? raw : NaN;
  if (!Number.isFinite(n) || n <= 0.5 || n > 5000) return null;
  return Math.round(n * 100) / 100;
}

function parseItem(item: Record<string, unknown>): EbayWhitelistListing | null {
  const itemId = String(first(item.itemId as string[] | string) ?? "").trim();
  const title = String(first(item.title as string[] | string) ?? "").trim();
  const price = parsePrice(item);
  if (!itemId || !title || price === null) return null;

  const listingInfo = first(item.listingInfo as Record<string, unknown>[] | Record<string, unknown>);
  const endRaw = listingInfo ? first(listingInfo.endTime as string[] | string) : undefined;
  const date_sold = endRaw ? String(endRaw).trim() || null : null;

  const conditionBlock = first(item.condition as Record<string, unknown>[] | Record<string, unknown>);
  const condition = conditionBlock
    ? String(
      first(conditionBlock.conditionDisplayName as string[] | string) ??
        first(conditionBlock.conditionId as string[] | string) ??
        "",
    ).trim() || null
    : null;

  const primaryCategory = first(
    item.primaryCategory as Record<string, unknown>[] | Record<string, unknown>,
  );
  const category = primaryCategory
    ? String(first(primaryCategory.categoryName as string[] | string) ?? "").trim() || null
    : null;

  const listing_url = String(first(item.viewItemURL as string[] | string) ?? "").trim() || null;
  const gallery = String(first(item.galleryURL as string[] | string) ?? "").trim();
  const picture = String(first(item.pictureURLSuperSize as string[] | string) ?? "").trim();
  const image_url = gallery || picture || null;

  return {
    listing_id: itemId,
    listing_title: title,
    price,
    condition,
    category,
    listing_url,
    image_url,
    date_sold,
  };
}

/** Up to 100 sold GB listings for a brand keyword search. */
export async function fetchEbaySoldListingsForWhitelist(
  brand: string,
): Promise<EbayWhitelistListing[]> {
  const keywords = brand.trim();
  if (!keywords) return [];

  const appId = ebayAppId();
  if (!appId) {
    console.error("[ebayWhitelist] EBAY_APP_ID missing");
    return [];
  }

  const url = buildFindingUrl(keywords, appId);
  console.log("[ebayWhitelist] findCompletedItems", JSON.stringify({ brand, entriesPerPage: ENTRIES_PER_PAGE }));

  let json: Record<string, unknown>;
  try {
    const res = await fetch(url, {
      signal: AbortSignal.timeout(FINDING_TIMEOUT_MS),
      headers: { Accept: "application/json" },
    });
    const text = await res.text();
    if (!res.ok) {
      console.error("[ebayWhitelist] HTTP", res.status, text.slice(0, 300));
      return [];
    }
    json = JSON.parse(text) as Record<string, unknown>;
  } catch (e) {
    console.error("[ebayWhitelist] request failed", e instanceof Error ? e.message : "unknown");
    return [];
  }

  const root = first(
    json.findCompletedItemsResponse as Record<string, unknown>[] | Record<string, unknown>,
  );
  if (!root) return [];

  const ack = String(first(root.ack as string[] | string) ?? "").toLowerCase();
  if (ack && ack !== "success" && ack !== "warning") {
    console.error("[ebayWhitelist] ack failure", ack);
    return [];
  }

  const searchResult = first(
    root.searchResult as Record<string, unknown>[] | Record<string, unknown>,
  );
  const itemsRaw = searchResult?.item;
  const itemArray: Record<string, unknown>[] = itemsRaw
    ? (Array.isArray(itemsRaw) ? itemsRaw : [itemsRaw]) as Record<string, unknown>[]
    : [];

  const out: EbayWhitelistListing[] = [];
  const seen = new Set<string>();
  for (const raw of itemArray) {
    const parsed = parseItem(raw);
    if (!parsed || seen.has(parsed.listing_id)) continue;
    seen.add(parsed.listing_id);
    out.push(parsed);
    if (out.length >= ENTRIES_PER_PAGE) break;
  }

  console.log("[ebayWhitelist] parsed", out.length, "for", brand);
  return out;
}

/**
 * Vinted / Depop catalog HTML scrape via ScrapingBee (top N listed items per brand).
 */
import { scrapePageHtml } from "./marketVisionScrape.ts";

export type HtmlWhitelistListing = {
  listing_id: string;
  listing_title: string;
  price: number;
  condition: string | null;
  image_url: string | null;
  listing_url: string | null;
};

const MAX_LISTINGS = 50;

function parseGbpPrice(raw: string): number | null {
  const m = raw.match(/£\s*(\d+(?:\.\d{1,2})?)/);
  if (!m) return null;
  const n = parseFloat(m[1]);
  if (!Number.isFinite(n) || n <= 0.5 || n > 5000) return null;
  return Math.round(n * 100) / 100;
}

function decodeHtml(s: string): string {
  return s
    .replace(/&amp;/g, "&")
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .trim();
}

/** Vinted UK: /items/{id}-slug */
export function parseVintedCatalogHtml(html: string, limit = MAX_LISTINGS): HtmlWhitelistListing[] {
  if (!html?.trim()) return [];

  const out: HtmlWhitelistListing[] = [];
  const seen = new Set<string>();

  const linkRe = /href="(\/items\/(\d+)(?:-[^"]*)?)"/gi;
  let m: RegExpExecArray | null;
  while ((m = linkRe.exec(html)) !== null && out.length < limit) {
    const path = m[1];
    const id = m[2];
    if (!id || seen.has(id)) continue;

    const start = Math.max(0, m.index - 800);
    const end = Math.min(html.length, m.index + 1200);
    const chunk = html.slice(start, end);

    let title =
      chunk.match(/"title"\s*:\s*"((?:\\.|[^"\\])*)"/i)?.[1] ??
      chunk.match(/data-testid="[^"]*title[^"]*"[^>]*>([^<]{4,120})</i)?.[1] ??
      chunk.match(/alt="([^"]{4,120})"/i)?.[1] ??
      "";
    title = decodeHtml(title.replace(/\\u002F/g, "/").replace(/\\"/g, '"'));
    if (!title || title.length < 3) {
      const slug = path.replace(/^\/items\/\d+-?/, "").replace(/"/g, "");
      title = slug ? decodeHtml(slug.replace(/-/g, " ")) : `Vinted item ${id}`;
    }

    const priceMatch = chunk.match(/£\s*(\d+(?:\.\d{1,2})?)/);
    const price = priceMatch ? parseGbpPrice(`£${priceMatch[1]}`) : null;
    if (price === null) continue;

    const img =
      chunk.match(/(https:\/\/[^"\s]*vinted[^"\s]*\.(?:jpg|jpeg|webp|png)[^"\s]*)/i)?.[1] ??
      chunk.match(/src="(https:\/\/[^"]+\.(?:jpg|jpeg|webp|png)[^"]*)"/i)?.[1] ??
      null;

    seen.add(id);
    out.push({
      listing_id: id,
      listing_title: title.slice(0, 500),
      price,
      condition: null,
      image_url: img,
      listing_url: `https://www.vinted.co.uk${path}`,
    });
  }

  return out.slice(0, limit);
}

/** Depop UK: /products/{slug} — slug ends with numeric id segment. */
export function parseDepopSearchHtml(html: string, limit = MAX_LISTINGS): HtmlWhitelistListing[] {
  if (!html?.trim()) return [];

  const out: HtmlWhitelistListing[] = [];
  const seen = new Set<string>();

  const linkRe = /href="(\/products\/([^"?#]+))"/gi;
  let m: RegExpExecArray | null;
  while ((m = linkRe.exec(html)) !== null && out.length < limit) {
    const path = m[1];
    const slug = m[2];
    if (!slug || slug.length < 3) continue;

    const idMatch = slug.match(/-(\d{6,})$/);
    const id = idMatch ? idMatch[1] : slug;
    if (seen.has(id)) continue;

    const start = Math.max(0, m.index - 800);
    const end = Math.min(html.length, m.index + 1200);
    const chunk = html.slice(start, end);

    let title =
      chunk.match(/"description"\s*:\s*"((?:\\.|[^"\\])*)"/i)?.[1] ??
      chunk.match(/"name"\s*:\s*"((?:\\.|[^"\\])*)"/i)?.[1] ??
      chunk.match(/alt="([^"]{4,120})"/i)?.[1] ??
      "";
    title = decodeHtml(title.replace(/\\u002F/g, "/").replace(/\\"/g, '"'));
    if (!title || title.length < 3) {
      title = decodeHtml(slug.replace(/-\d+$/, "").replace(/-/g, " "));
    }
    if (!title || title.length < 3) continue;

    const priceMatch = chunk.match(/£\s*(\d+(?:\.\d{1,2})?)/);
    const price = priceMatch ? parseGbpPrice(`£${priceMatch[1]}`) : null;
    if (price === null) continue;

    const img =
      chunk.match(/(https:\/\/media-photos\.depop\.com[^"\s]+)/i)?.[1] ??
      chunk.match(/src="(https:\/\/[^"]+depop[^"]+\.(?:jpg|jpeg|webp|png)[^"]*)"/i)?.[1] ??
      null;

    seen.add(id);
    out.push({
      listing_id: id,
      listing_title: title.slice(0, 500),
      price,
      condition: null,
      image_url: img,
      listing_url: `https://www.depop.com${path}`,
    });
  }

  return out.slice(0, limit);
}

